  if (!kBrowserOnlyNativeStartup) {
    const auto descendant_stream = aux::descendants::InspectStream();
    if (descendant_stream == aux::descendants::Result::unknown ||
        descendant_stream == aux::descendants::Result::refused)
      result = AuxDevelopmentWorkerDrain::untracked;
    else if (descendant_stream == aux::descendants::Result::pending)
      result = AuxDevelopmentWorkerDrain::pending;
  }
  // Browser-only settlement below covers actual provider/main/broker/image
  // lifetimes. It neither observes nor reports an ES descendant census.
  {
    std::lock_guard<std::mutex> lock(state_->clean->mutex);
    state_->clean->admission_closed = true;
  }
