    if (!stdios_val->IsArray()) {
      THROW_ERR_INVALID_ARG_TYPE(env, "options.stdio must be an array");
      return Nothing<void>();
    }
    Local<Array> stdios = stdios_val.As<Array>();

    uint32_t len = stdios->Length();
    options_stdio->resize(len);

    for (uint32_t i = 0; i < len; i++) {
      Local<Value> val;
      if (!stdios->Get(context, i).ToLocal(&val)) {
        return Nothing<void>();
      }
      Local<Object> stdio = val.As<Object>();
      Local<Value> type;
      if (!stdio->Get(context, env->type_string()).ToLocal(&type)) {
        return Nothing<void>();
      }

      if (type->StrictEquals(env->ignore_string())) {
        (*options_stdio)[i].flags = UV_IGNORE;
      } else if (type->StrictEquals(env->pipe_string())) {
        (*options_stdio)[i].flags = static_cast<uv_stdio_flags>(
            UV_CREATE_PIPE | UV_READABLE_PIPE | UV_WRITABLE_PIPE);
        if (!StreamForWrap(env, stdio).To(&(*options_stdio)[i].data.stream)) {
          return Nothing<void>();
        }
      } else if (type->StrictEquals(env->overlapped_string())) {
        (*options_stdio)[i].flags =
            static_cast<uv_stdio_flags>(UV_CREATE_PIPE | UV_READABLE_PIPE |
                                        UV_WRITABLE_PIPE | UV_OVERLAPPED_PIPE);
        if (!StreamForWrap(env, stdio).To(&(*options_stdio)[i].data.stream)) {
          return Nothing<void>();
        }
      } else if (type->StrictEquals(env->wrap_string())) {
        (*options_stdio)[i].flags = UV_INHERIT_STREAM;
        if (!StreamForWrap(env, stdio).To(&(*options_stdio)[i].data.stream)) {
          return Nothing<void>();
        }
      } else {
        Local<String> fd_key = env->fd_string();
        Local<Value> fd_value;
        if (!stdio->Get(context, fd_key).ToLocal(&fd_value)) {
          return Nothing<void>();
        }
        CHECK(fd_value->IsNumber());
        int fd = FromV8Value<int>(fd_value);
        (*options_stdio)[i].flags = UV_INHERIT_FD;
        (*options_stdio)[i].data.fd = fd;
      }
    }
    return JustVoid();
  }

  static void Spawn(const FunctionCallbackInfo<Value>& args) {
    // Reserve before callback-capable argument/stdio property access. Failure
    // cannot enter the ordinary unrestricted producer as a fallback.
    struct PendingExec {
      void* token = AuxNativeExecBeginCurrent();
      ~PendingExec() { if (token) AuxNativeExecSpawnFailed(token); }
      void* TakeCreated() noexcept {
        void* saved = token;
        token = nullptr;
        return saved;
      }
    } pending;
    if (!pending.token) { args.GetReturnValue().Set(UV_EPERM); return; }
    Environment* env = Environment::GetCurrent(args);
    Local<Context> context = env->context();
    ProcessWrap* wrap;
    ASSIGN_OR_RETURN_UNWRAP(&wrap, args.This());
    int err = 0;
    if (wrap->aux_exec_reservation_) { args.GetReturnValue().Set(UV_EBUSY); return; }

    uv_process_options_t options;
    memset(&options, 0, sizeof(uv_process_options_t));

    options.exit_cb = OnExit;

    // args[0] file
    CHECK(args[0]->IsString());
    node::Utf8Value file(env->isolate(), args[0]);
    options.file = *file;

    THROW_IF_INSUFFICIENT_PERMISSIONS(
        env, permission::PermissionScope::kChildProcess, file.ToStringView());

    // args[6] uid
    Local<Value> uid_v = args[6];
    if (!uid_v->IsUndefined() && !uid_v->IsNull()) {
      CHECK(uid_v->IsInt32());
      const int32_t uid = uid_v.As<Int32>()->Value();
      options.flags |= UV_PROCESS_SETUID;
      options.uid = static_cast<uv_uid_t>(uid);
    }

    // args[7] gid
    Local<Value> gid_v = args[7];
    if (!gid_v->IsUndefined() && !gid_v->IsNull()) {
      CHECK(gid_v->IsInt32());
      const int32_t gid = gid_v.As<Int32>()->Value();
      options.flags |= UV_PROCESS_SETGID;
      options.gid = static_cast<uv_gid_t>(gid);
    }

    // Undocumented feature of Win32 CreateProcess API allows spawning
    // batch files directly but is potentially insecure because arguments
    // are not escaped (and sometimes cannot be unambiguously escaped),
    // hence why they are rejected here.
#ifdef _WIN32
    if (IsWindowsBatchFile(options.file))
      err = UV_EINVAL;
#endif

    // args[1] args
    std::vector<char*> options_args;
    std::vector<std::string> args_vals;
    if (args[1]->IsArray()) {
      Local<Array> js_argv = args[1].As<Array>();
      int argc = js_argv->Length();
      CHECK_LT(argc, INT_MAX);  // Check for overflow.
      args_vals.reserve(argc);
      for (int i = 0; i < argc; i++) {
        Local<Value> val;
        if (!js_argv->Get(context, i).ToLocal(&val)) {
          return;
        }
        node::Utf8Value arg(env->isolate(), val);
        args_vals.emplace_back(arg.ToString());
      }
      options_args.resize(args_vals.size() + 1);
      for (size_t i = 0; i < args_vals.size(); i++) {
        options_args[i] = const_cast<char*>(args_vals[i].c_str());
        CHECK_NOT_NULL(options_args[i]);
      }
      options_args.back() = nullptr;
      options.args = options_args.data();
    }

    // args[2] cwd
    node::Utf8Value cwd(env->isolate(),
                        args[2]->IsString() ? args[2] : Local<Value>());
    if (cwd.length() > 0) {
      options.cwd = *cwd;
    }

    // args[3] envPairs
    std::vector<char*> options_env;
    std::vector<std::string> env_vals;
    if (args[3]->IsArray()) {
      Local<Array> env_opt = args[3].As<Array>();
      int envc = env_opt->Length();
      CHECK_LT(envc, INT_MAX);            // Check for overflow.
      env_vals.reserve(envc);
      for (int i = 0; i < envc; i++) {
        Local<Value> val;
        if (!env_opt->Get(context, i).ToLocal(&val)) {
          return;
        }
        node::Utf8Value pair(env->isolate(), val);
        env_vals.emplace_back(pair.ToString());
      }
      options_env.resize(env_vals.size() + 1);
      for (size_t i = 0; i < env_vals.size(); i++) {
        options_env[i] = const_cast<char*>(env_vals[i].c_str());
        CHECK_NOT_NULL(options_env[i]);
      }
      options_env.back() = nullptr;
      options.env = options_env.data();
    }

    // args[4] stdio
    std::vector<uv_stdio_container_t> options_stdio;
    if (ParseStdioOptions(env, args[4], &options_stdio).IsNothing()) {
      return;
    }
    options.stdio = options_stdio.data();
    options.stdio_count = options_stdio.size();

    // args[5] flags (detached, windowsHide, windowsVerbatimArguments)
    CHECK(args[5]->IsUint32());
    const uint32_t flags = args[5].As<Uint32>()->Value();

    if (flags & kProcessFlagWindowsHide) {
      options.flags |= UV_PROCESS_WINDOWS_HIDE;
    }

    if (env->hide_console_windows()) {
      options.flags |= UV_PROCESS_WINDOWS_HIDE_CONSOLE;
    }

    if (flags & kProcessFlagWindowsVerbatimArguments) {
      options.flags |= UV_PROCESS_WINDOWS_VERBATIM_ARGUMENTS;
    }

    if (flags & kProcessFlagDetached) {
      options.flags |= UV_PROCESS_DETACHED;
    }

    AuxExecNativeTaskBoundary task_boundary{};
  AuxExecNativeRuntimeBoundary runtime_boundary{};
    AuxExecNativeDeniedRoots denied_roots{};
    AuxExecSpawnEnvelope envelope;
    if (err == 0 && !AuxExecDescriptorOptionsAllowed(options)) err = UV_EPERM;
    if (err == 0 && AuxNativeExecCopyDeniedRoots(pending.token, &denied_roots) != 0)
      err = UV_EPERM;
    if (err == 0 && AuxNativeExecCopyTaskBoundary(pending.token,&task_boundary)!=0 ||
      AuxNativeExecCopyRuntimeBoundary(pending.token,&runtime_boundary)!=0 ||
        !envelope.Prepare(options, denied_roots,task_boundary,runtime_boundary)) err = UV_EPERM;
    if (err == 0) {
      options.file = envelope.File();
      options.args = envelope.Args();
      options.cwd = envelope.Cwd();
      options.env = envelope.Env();
      if (!AuxNativeExecCanSpawn(pending.token)) err = UV_EPERM;
    }
    if (err == 0) {
      if (AuxNativeExecEnterUvSpawn(pending.token) != 0) err = UV_EPERM;
      else {
        err = uv_spawn(env->event_loop(), &wrap->process_, &options);
        if (AuxNativeExecLeaveUvSpawn() == 1)
          wrap->aux_exec_reservation_ = pending.TakeCreated();
        // Publish custody before this or any JS-visible result operation.
        wrap->MarkAsInitialized();
      }
    }

    if (err == 0) {
      CHECK_EQ(wrap->process_.data, wrap);
      if (wrap->object()
              ->Set(context,
                    env->pid_string(),
                    Integer::New(env->isolate(), wrap->process_.pid))
              .IsNothing()) {
        return;
      }
    }

    args.GetReturnValue().Set(err);
  }

  static void Kill(const FunctionCallbackInfo<Value>& args) {
    Environment* env = Environment::GetCurrent(args);
    ProcessWrap* wrap;
    ASSIGN_OR_RETURN_UNWRAP(&wrap, args.This());
    int signal;
    if (!args[0]->Int32Value(env->context()).To(&signal)) {
      return;
    }
#ifdef _WIN32
    if (signal != SIGKILL && signal != SIGTERM && signal != SIGINT &&
        signal != SIGQUIT && signal != 0) {
      signal = SIGKILL;
    }
#endif
    int err = uv_process_kill(&wrap->process_, signal);
    args.GetReturnValue().Set(err);
  }

  static void OnExit(uv_process_t* handle,
                     int64_t exit_status,
                     int term_signal) {
    ProcessWrap* wrap = ContainerOf(&ProcessWrap::process_, handle);
    CHECK_EQ(&wrap->process_, handle);
    AuxNativeExecDirectExitObserved(wrap->aux_exec_reservation_,
                                   handle->pid, exit_status, term_signal);
    // The host retains its direct-child/descendant uncertainty even if JS
    // callbacks fail or this ProcessWrap is destroyed after the native exit.

    Environment* env = wrap->env();
    HandleScope handle_scope(env->isolate());
    Context::Scope context_scope(env->context());

    Local<Value> argv[] = {
      Number::New(env->isolate(), static_cast<double>(exit_status)),
      OneByteString(env->isolate(), signo_string(term_signal))
    };

    wrap->MakeCallback(env->onexit_string(), arraysize(argv), argv);
  }

  void OnClose() override {AuxNativeExecOriginalHandleClosed(aux_exec_reservation_);}
  uv_process_t process_;
  void* aux_exec_reservation_ = nullptr;
};


}  // anonymous namespace
}  // namespace node

