// IN AN ACTION OF CONTRACT, NEGLIGENCE OR OTHER TORTIOUS ACTION, ARISING
// OUT OF OR IN CONNECTION WITH THE USE OR PERFORMANCE OF THIS SOFTWARE.

#if defined(__linux__)

static char *
pty_getproc(int fd, char *tty) {
  FILE *f;
  char *path, *buf;
  size_t len;
  int ch;
  pid_t pgrp;
  int r;

  if ((pgrp = tcgetpgrp(fd)) == -1) {
    return NULL;
  }

  r = asprintf(&path, "/proc/%lld/cmdline", (long long)pgrp);
  if (r == -1 || path == NULL) return NULL;

  if ((f = fopen(path, "r")) == NULL) {
    free(path);
    return NULL;
  }

  free(path);

  len = 0;
  buf = NULL;
  while ((ch = fgetc(f)) != EOF) {
    if (ch == '\0') break;
    buf = (char *)realloc(buf, len + 2);
    if (buf == NULL) return NULL;
    buf[len++] = ch;
  }

  if (buf != NULL) {
    buf[len] = '\0';
  }

  fclose(f);
  return buf;
}

#elif defined(__APPLE__)

static char *
pty_getproc(int fd) {
  int mib[4] = { CTL_KERN, KERN_PROC, KERN_PROC_PID, 0 };
  size_t size;
  struct kinfo_proc kp;

  if ((mib[3] = tcgetpgrp(fd)) == -1) {
    return NULL;
  }

  size = sizeof kp;
  if (sysctl(mib, 4, &kp, &size, NULL, 0) == -1) {
    return NULL;
  }

  if (size != (sizeof kp) || *kp.kp_proc.p_comm == '\0') {
    return NULL;
  }

  return strdup(kp.kp_proc.p_comm);
}

#else

static char *
pty_getproc(int fd, char *tty) {
  return NULL;
}

#endif

#if defined(__APPLE__)
static void
pty_posix_spawn(char** argv, char** env,
                const struct termios *termp,
                const struct winsize *winp,
                int* master,
                pid_t* pid,
                int* err, NativePtyReservation& reservation, NativeExecReservation& exec_reservation) {
  int low_fds[3] = {-1, -1, -1};
  size_t count = 0;
  int master_fd = -1, slave = -1;
  pid_t child_pid = -1;
  posix_spawn_file_actions_t acts;
  posix_spawnattr_t attrs;
  bool acts_initialized = false, attrs_initialized = false;
  sigset_t signal_set;
  char slave_pty_name[128];
  AuxExecNativeDeniedRoots denied_roots{};
  AuxExecNativeTaskBoundary task_boundary{};
  AuxExecSpawnEnvelope envelope;
  uv_process_options_t command{};
  const int flags = POSIX_SPAWN_CLOEXEC_DEFAULT |
                    POSIX_SPAWN_SETSIGDEF |
                    POSIX_SPAWN_SETSIGMASK |
                    POSIX_SPAWN_SETSID;
  *master = -1;
  *pid = -1;
  *err = 0;
  command.file = argv[0];
  command.args = argv;
  command.env = env;
  command.cwd = argv[1][0] ? argv[1] : nullptr;
  // Preserve the authenticated helper's original cwd argv. Relative cwd would
  // depend on a mutable parent directory, so protected routing refuses it.
  if ((argv[1][0] && argv[1][0] != '/') ||
      AuxNativeExecCopyDeniedRoots(exec_reservation.Handle(), &denied_roots) != 0 ||
      AuxNativeExecCopyTaskBoundary(exec_reservation.Handle(),&task_boundary)!=0 ||
      !envelope.Prepare(command, denied_roots,task_boundary)) {
    *err = EPERM;
    goto done;
  }

  // Keep initially closed stdio slots occupied until the PTY is configured.
  while (count < 3) {
    const int fd = posix_openpt(O_RDWR);
    if (fd == -1) {
      *err = errno;
      goto done;
    }
    low_fds[count++] = fd;
    if (fd >= STDERR_FILENO) break;
  }

  master_fd = posix_openpt(O_RDWR);
  if (master_fd == -1) {
    *err = errno;
    goto done;
  }
  if (grantpt(master_fd) == -1) {
    *err = errno;
    goto done;
  }
  if (unlockpt(master_fd) == -1) {
    *err = errno;
    goto done;
  }

  // Use TIOCPTYGNAME instead of ptsname() to avoid threading problems.
  if (ioctl(master_fd, TIOCPTYGNAME, slave_pty_name) == -1) {
    *err = errno;
    goto done;
  }
  slave = open(slave_pty_name, O_RDWR | O_NOCTTY);
  if (slave == -1) {
    *err = errno;
    goto done;
  }
  if (termp && tcsetattr(slave, TCSANOW, termp) == -1) {
    *err = errno;
    goto done;
  }
  if (winp && ioctl(slave, TIOCSWINSZ, winp) == -1) {
    *err = errno;
    goto done;
  }

  *err = posix_spawn_file_actions_init(&acts);
  if (*err != 0) goto done;
  acts_initialized = true;
  *err = posix_spawn_file_actions_adddup2(&acts, slave, STDIN_FILENO);
  if (*err != 0) goto done;
  *err = posix_spawn_file_actions_adddup2(&acts, slave, STDOUT_FILENO);
  if (*err != 0) goto done;
  *err = posix_spawn_file_actions_adddup2(&acts, slave, STDERR_FILENO);
  if (*err != 0) goto done;
  *err = posix_spawn_file_actions_addclose(&acts, slave);
  if (*err != 0) goto done;
  *err = posix_spawn_file_actions_addclose(&acts, master_fd);
  if (*err != 0) goto done;

  *err = posix_spawnattr_init(&attrs);
  if (*err != 0) goto done;
  attrs_initialized = true;
  *err = posix_spawnattr_setflags(&attrs, flags);
  if (*err != 0) goto done;
  if (sigfillset(&signal_set) == -1) {
    *err = errno;
    goto done;
  }
  *err = posix_spawnattr_setsigdefault(&attrs, &signal_set);
  if (*err != 0) goto done;
  if (sigemptyset(&signal_set) == -1) {
    *err = errno;
    goto done;
  }
  *err = posix_spawnattr_setsigmask(&attrs, &signal_set);
  if (*err != 0) goto done;

  do {
    if (!reservation.CanSpawn() || !exec_reservation.CanSpawn()) {
      *err = ECANCELED;
      goto done;
    }
    *err = posix_spawn(&child_pid, envelope.File(), &acts, &attrs,
                       envelope.Args(), envelope.Env());
  } while (*err == EINTR);
  if (*err == 0) {
    reservation.ChildCreated(child_pid);
    exec_reservation.ChildCreated(child_pid);
    *pid = child_pid;
    *master = master_fd;
    master_fd = -1;
  }
done:
  // Cleanup must not turn a created child into a reported spawn failure:
  // the prepared sole reaper receives its identity immediately on return.
  if (acts_initialized) posix_spawn_file_actions_destroy(&acts);
  if (attrs_initialized) posix_spawnattr_destroy(&attrs);
  if (slave != -1) close(slave);
  if (master_fd != -1) close(master_fd);
  while (count > 0) close(low_fds[--count]);
}
#endif

/**
 * Init
 */

Napi::Object init(Napi::Env env, Napi::Object exports) {
  exports.Set("fork",    Napi::Function::New(env, PtyFork));
  exports.Set("open",    Napi::Function::New(env, PtyOpen));
  exports.Set("resize",  Napi::Function::New(env, PtyResize));
  exports.Set("process", Napi::Function::New(env, PtyGetProc));
  return exports;
}

// Linked initializer only: the actual host registers it in the original main
// Environment after genuine supervised/ES admission. No dynamic module export.
extern "C" napi_value AuxInitializeFixedPty(napi_env env,napi_value exports) {
  try { return init(Napi::Env(env),Napi::Object(env,exports)); }
  catch(const Napi::Error& error) {error.ThrowAsJavaScriptException();return nullptr;}
  catch(...) {napi_throw_error(env,"AUX_PTY_INITIALIZER_FAILED","Fixed PTY initializer interrupted");return nullptr;}
}

