struct DelBuf {
  int len;
  DelBuf(int len) : len(len) {}
  void operator()(char **p) {
    if (p == nullptr)
      return;
    for (int i = 0; i < len; i++)
      free(p[i]);
    delete[] p;
  }
};

static char* pty_duplicate_argument(const char* argument) {
  char* copy = strdup(argument);
  if (copy == nullptr) throw std::bad_alloc();
  return copy;
}

Napi::Value PtyFork(const Napi::CallbackInfo& info) {
  NativePtyReservation reservation(AuxNativePtyBeginCurrent());
  NativeExecReservation exec_reservation(AuxNativeExecBeginCurrent());
  Napi::Env napiEnv(info.Env());
  Napi::HandleScope scope(napiEnv);
  if (reservation.Handle() == nullptr || exec_reservation.Handle() == nullptr)
    throw Napi::Error::New(napiEnv, "Native PTY creation is unavailable");
#if !defined(__APPLE__)
  throw Napi::Error::New(napiEnv, "Protected PTY creation requires the macOS descriptor policy");
#endif

  if (info.Length() != 11 ||
      !info[0].IsString() ||
      !info[1].IsArray() ||
      !info[2].IsArray() ||
      !info[3].IsString() ||
      !info[4].IsNumber() ||
      !info[5].IsNumber() ||
      !info[6].IsNumber() ||
      !info[7].IsNumber() ||
      !info[8].IsBoolean() ||
      !info[9].IsString() ||
      !info[10].IsFunction()) {
    throw Napi::Error::New(napiEnv, "Usage: pty.fork(file, args, env, cwd, cols, rows, uid, gid, utf8, helperPath, onexit)");
  }

  // file
  std::string file = info[0].As<Napi::String>();

  // args
  Napi::Array argv_ = info[1].As<Napi::Array>();

  // env
  Napi::Array env_ = info[2].As<Napi::Array>();
  int envc = env_.Length();
  std::unique_ptr<char *, DelBuf> env_unique_ptr(new char *[envc + 1](), DelBuf(envc + 1));
  char **env = env_unique_ptr.get();
  env[envc] = NULL;
  for (int i = 0; i < envc; i++) {
    std::string pair = env_.Get(i).As<Napi::String>();
    env[i] = pty_duplicate_argument(pair.c_str());
  }

  // cwd
  std::string cwd_ = info[3].As<Napi::String>();

  // size
  struct winsize winp;
  winp.ws_col = info[4].As<Napi::Number>().Int32Value();
  winp.ws_row = info[5].As<Napi::Number>().Int32Value();
  winp.ws_xpixel = 0;
  winp.ws_ypixel = 0;

#if !defined(__APPLE__)
  // uid / gid
  int uid = info[6].As<Napi::Number>().Int32Value();
  int gid = info[7].As<Napi::Number>().Int32Value();
#endif

  // termios
  struct termios t = termios();
  struct termios *term = &t;
  term->c_iflag = ICRNL | IXON | IXANY | IMAXBEL | BRKINT;
  if (info[8].As<Napi::Boolean>().Value()) {
#if defined(IUTF8)
    term->c_iflag |= IUTF8;
#endif
  }
  term->c_oflag = OPOST | ONLCR;
  term->c_cflag = CREAD | CS8 | HUPCL;
  term->c_lflag = ICANON | ISIG | IEXTEN | ECHO | ECHOE | ECHOK | ECHOKE | ECHOCTL;

  term->c_cc[VEOF] = 4;
  term->c_cc[VEOL] = -1;
  term->c_cc[VEOL2] = -1;
  term->c_cc[VERASE] = 0x7f;
  term->c_cc[VWERASE] = 23;
  term->c_cc[VKILL] = 21;
  term->c_cc[VREPRINT] = 18;
  term->c_cc[VINTR] = 3;
  term->c_cc[VQUIT] = 0x1c;
  term->c_cc[VSUSP] = 26;
  term->c_cc[VSTART] = 17;
  term->c_cc[VSTOP] = 19;
  term->c_cc[VLNEXT] = 22;
  term->c_cc[VDISCARD] = 15;
  term->c_cc[VMIN] = 1;
  term->c_cc[VTIME] = 0;

  #if (__APPLE__)
  term->c_cc[VDSUSP] = 25;
  term->c_cc[VSTATUS] = 20;
  #endif

  cfsetispeed(term, B38400);
  cfsetospeed(term, B38400);

  // Keep helperPath's argument shape, but only native policy selects the image.
  char helper_path[4096] = {};
  uint32_t helper_path_bytes = 0;
  if (AuxNativePtyCopyHelperPath(reservation.Handle(), helper_path,
                               sizeof(helper_path), &helper_path_bytes) != 0 ||
      helper_path_bytes < 2 || helper_path_bytes > sizeof(helper_path) ||
      helper_path[0] != '/' || helper_path[helper_path_bytes - 1] != '\0' ||
      memchr(helper_path, '\0', helper_path_bytes - 1) != nullptr) {
    throw Napi::Error::New(napiEnv, "Authenticated native PTY helper unavailable");
  }

  int master = -1;
  ScopedPtyMaster master_owner(master,reservation.Handle(), exec_reservation.Handle());
  PreparedExitCallback exit_callback(
      napiEnv, info[10].As<Napi::Function>(), reservation.Handle(), exec_reservation.Handle());
  pid_t pid;
#if defined(__APPLE__)
  int argc = argv_.Length();
  int argl = argc + 4;
  std::unique_ptr<char *, DelBuf> argv_unique_ptr(new char *[argl](), DelBuf(argl));
  char **argv = argv_unique_ptr.get();
  argv[0] = pty_duplicate_argument(helper_path);
  argv[1] = pty_duplicate_argument(cwd_.c_str());
  argv[2] = pty_duplicate_argument(file.c_str());
  argv[argl - 1] = NULL;
  for (int i = 0; i < argc; i++) {
    std::string arg = argv_.Get(i).As<Napi::String>();
    argv[i + 3] = pty_duplicate_argument(arg.c_str());
  }

  int err = -1;
  pty_posix_spawn(argv, env, term, &winp, &master, &pid, &err, reservation, exec_reservation);
  if (err != 0) {
    throw Napi::Error::New(napiEnv, "posix_spawnp failed.");
  }
  exit_callback.Publish(pid);
  if (pty_nonblock(master) == -1) {
    throw Napi::Error::New(napiEnv, "Could not set master fd to nonblocking.");
  }
#else
  int argc = argv_.Length();
  int argl = argc + 2;
  std::unique_ptr<char *, DelBuf> argv_unique_ptr(new char *[argl](), DelBuf(argl));
  char** argv = argv_unique_ptr.get();
  argv[0] = pty_duplicate_argument(file.c_str());
  argv[argl - 1] = NULL;
  for (int i = 0; i < argc; i++) {
    std::string arg = argv_.Get(i).As<Napi::String>();
    argv[i + 1] = pty_duplicate_argument(arg.c_str());
  }

  sigset_t newmask, oldmask;
  struct sigaction sig_action;
  // temporarily block all signals
  // this is needed due to a race condition in openpty
  // and to avoid running signal handlers in the child
  // before exec* happened
  sigfillset(&newmask);
  pthread_sigmask(SIG_SETMASK, &newmask, &oldmask);

  if (!reservation.CanSpawn()) {
    pthread_sigmask(SIG_SETMASK, &oldmask, NULL);
    throw Napi::Error::New(napiEnv, "Native PTY creation is closed");
  }
  pid = forkpty(&master, nullptr, static_cast<termios*>(term), static_cast<winsize*>(&winp));
  if (pid > 0) reservation.ChildCreated(pid);

  if (!pid) {
    // remove all signal handler from child
    sig_action.sa_handler = SIG_DFL;
    sig_action.sa_flags = 0;
    sigemptyset(&sig_action.sa_mask);
    for (int i = 0 ; i < NSIG ; i++) {    // NSIG is a macro for all signals + 1
      sigaction(i, &sig_action, NULL);
    }
  }

  // reenable signals
  pthread_sigmask(SIG_SETMASK, &oldmask, NULL);

  switch (pid) {
    case -1:
      throw Napi::Error::New(napiEnv, "forkpty(3) failed.");
    case 0:
      if (strlen(cwd_.c_str())) {
        if (chdir(cwd_.c_str()) == -1) {
          perror("chdir(2) failed.");
          _exit(1);
        }
      }

      if (uid != -1 && gid != -1) {
        if (setgid(gid) == -1) {
          perror("setgid(2) failed.");
          _exit(1);
        }
        if (setuid(uid) == -1) {
          perror("setuid(2) failed.");
          _exit(1);
        }
      }

      {
        char **old = environ;
        environ = env;
        execvp(argv[0], argv);
        environ = old;
        perror("execvp(3) failed.");
        _exit(1);
      }
    default:
      exit_callback.Publish(pid);
      if (pty_nonblock(master) == -1) {
        throw Napi::Error::New(napiEnv, "Could not set master fd to nonblocking.");
      }
  }
#endif

  Napi::Object obj = Napi::Object::New(napiEnv);
  obj.Set("fd", Napi::Number::New(napiEnv, master));
  obj.Set("pid", Napi::Number::New(napiEnv, pid));
  obj.Set("pty", Napi::String::New(napiEnv, ptsname(master)));
  // Immutable private callback, not a caller-selected reservation or PID.
  struct TransportTokens{void* pty;void* exec;};
  auto tokens=std::make_unique<TransportTokens>(TransportTokens{reservation.Handle(),exec_reservation.Handle()});
  napi_value closed;
  auto callback=[](napi_env env,napi_callback_info info)->napi_value{void* data=nullptr;size_t count=0;if(napi_get_cb_info(env,info,&count,nullptr,nullptr,&data)!=napi_ok)return nullptr;auto* tokens=static_cast<TransportTokens*>(data);AuxNativePtyTransportClosed(tokens->pty);AuxNativeExecOriginalHandleClosed(tokens->exec);napi_value value;napi_get_undefined(env,&value);return value;};
  if(napi_create_function(napiEnv,"auxOriginalTransportClosed",NAPI_AUTO_LENGTH,callback,tokens.get(),&closed)!=napi_ok)throw Napi::Error::New(napiEnv,"PTY transport completion capture failed");
  if(napi_add_finalizer(napiEnv,closed,tokens.get(),[](napi_env,void* data,void*){delete static_cast<TransportTokens*>(data);},nullptr,nullptr)!=napi_ok)throw Napi::Error::New(napiEnv,"PTY transport finalizer capture failed");
  tokens.release();
  const napi_property_descriptor property{"auxOriginalTransportClosed",nullptr,nullptr,nullptr,nullptr,closed,napi_default,nullptr};
  if(napi_define_properties(napiEnv,obj,1,&property)!=napi_ok)throw Napi::Error::New(napiEnv,"PTY transport completion binding failed");

  master_owner.Release();
  return obj;
}

Napi::Value PtyOpen(const Napi::CallbackInfo& info) {
  Napi::Env env(info.Env());
  Napi::HandleScope scope(env);

  if (info.Length() != 2 ||
      !info[0].IsNumber() ||
      !info[1].IsNumber()) {
    throw Napi::Error::New(env, "Usage: pty.open(cols, rows)");
  }

  // size
  struct winsize winp;
  winp.ws_col = info[0].As<Napi::Number>().Int32Value();
  winp.ws_row = info[1].As<Napi::Number>().Int32Value();
  winp.ws_xpixel = 0;
  winp.ws_ypixel = 0;

  // pty
  int master, slave;
  int ret = openpty(&master, &slave, nullptr, NULL, static_cast<winsize*>(&winp));

  if (ret == -1) {
    throw Napi::Error::New(env, "openpty(3) failed.");
  }

  if (pty_nonblock(master) == -1) {
    throw Napi::Error::New(env, "Could not set master fd to nonblocking.");
  }

  if (pty_nonblock(slave) == -1) {
    throw Napi::Error::New(env, "Could not set slave fd to nonblocking.");
  }

  Napi::Object obj = Napi::Object::New(env);
  obj.Set("master", Napi::Number::New(env, master));
  obj.Set("slave", Napi::Number::New(env, slave));
  obj.Set("pty", Napi::String::New(env, ptsname(master)));

  return obj;
}

Napi::Value PtyResize(const Napi::CallbackInfo& info) {
  Napi::Env env(info.Env());
  Napi::HandleScope scope(env);

  if (info.Length() != 3 ||
      !info[0].IsNumber() ||
      !info[1].IsNumber() ||
      !info[2].IsNumber()) {
    throw Napi::Error::New(env, "Usage: pty.resize(fd, cols, rows)");
  }

  int fd = info[0].As<Napi::Number>().Int32Value();

  struct winsize winp;
  winp.ws_col = info[1].As<Napi::Number>().Int32Value();
  winp.ws_row = info[2].As<Napi::Number>().Int32Value();
  winp.ws_xpixel = 0;
  winp.ws_ypixel = 0;

  if (ioctl(fd, TIOCSWINSZ, &winp) == -1) {
    switch (errno) {
      case EBADF:
        throw Napi::Error::New(env, "ioctl(2) failed, EBADF");
      case EFAULT:
        throw Napi::Error::New(env, "ioctl(2) failed, EFAULT");
      case EINVAL:
        throw Napi::Error::New(env, "ioctl(2) failed, EINVAL");
      case ENOTTY:
        throw Napi::Error::New(env, "ioctl(2) failed, ENOTTY");
    }
    throw Napi::Error::New(env, "ioctl(2) failed");
  }

  return env.Undefined();
}

/**
 * Foreground Process Name
 */
Napi::Value PtyGetProc(const Napi::CallbackInfo& info) {
  Napi::Env env(info.Env());
  Napi::HandleScope scope(env);

#if defined(__APPLE__)
  if (info.Length() != 1 ||
      !info[0].IsNumber()) {
    throw Napi::Error::New(env, "Usage: pty.process(pid)");
  }

  int fd = info[0].As<Napi::Number>().Int32Value();
  char *name = pty_getproc(fd);
#else
  if (info.Length() != 2 ||
      !info[0].IsNumber() ||
      !info[1].IsString()) {
    throw Napi::Error::New(env, "Usage: pty.process(fd, tty)");
  }

  int fd = info[0].As<Napi::Number>().Int32Value();

  std::string tty_ = info[1].As<Napi::String>();
  char *tty = strdup(tty_.c_str());
  char *name = pty_getproc(fd, tty);
  free(tty);
#endif

  if (name == NULL) {
    return env.Undefined();
  }

  Napi::String name_ = Napi::String::New(env, name);
  free(name);
  return name_;
}

/**
 * Nonblocking FD
 */

static int
pty_nonblock(int fd) {
  int flags = fcntl(fd, F_GETFL, 0);
  if (flags == -1) return -1;
  return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

